'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const positions = [];
for (let i = 0; i < n; i++) {
  if (input[i + 1] === 1) positions.push(i + 1);
}

let answer = 0;
for (let i = 0; i < positions.length; i++) {
  const previous = i === 0 ? 0 : positions[i - 1];
  const next = i + 1 === positions.length ? n + 1 : positions[i + 1];
  answer += (positions[i] - previous) * (next - positions[i]);
}

console.log(answer);
